import{_ as e,c as t,o as i,ag as n}from"./chunks/framework.DQvKz0xt.js";const m=JSON.parse('{"title":"过渡 (Transitions) - Rive 编辑器","description":"状态机 (State Machines) 过渡为状态机提供逻辑路线图。本节将介绍过渡的配置属性和注意事项。","frontmatter":{"title":"过渡 (Transitions) - Rive 编辑器","description":"状态机 (State Machines) 过渡为状态机提供逻辑路线图。本节将介绍过渡的配置属性和注意事项。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 状态机, 过渡"}]]},"headers":[],"relativePath":"editor/state-machine/transitions.md","filePath":"editor/state-machine/transitions.md","lastUpdated":1774838907000}'),r={name:"editor/state-machine/transitions.md"};function o(s,a,p,h,l,d){return i(),t("div",null,[...a[0]||(a[0]=[n('<p>状态机 (State Machines)</p><h1 id="过渡-transitions" tabindex="-1">过渡 (Transitions) <a class="header-anchor" href="#过渡-transitions" aria-label="Permalink to &quot;过渡 (Transitions)&quot;">​</a></h1><p>过渡为状态机提供逻辑路线图。本节将介绍过渡的配置属性和注意事项。</p><h2 id="​-创建过渡" tabindex="-1"><a href="#creating-a-new-transition">​</a> 创建过渡 <a class="header-anchor" href="#​-创建过渡" aria-label="Permalink to &quot;[​](#creating-a-new-transition) 创建过渡&quot;">​</a></h2><p>将鼠标移到某个状态附近，当出现椭圆图标时，点击并拖动到目标状态即可创建过渡。连接完成后会显示一个带箭头的椭圆，指示过渡方向。 <img src="https://help.rive.app/images/image_0.png" alt="创建过渡"> 你可以在两个状态之间创建多条过渡，每条设置不同的条件，实现&quot;或 (OR)&quot;逻辑。 <img src="https://help.rive.app/images/image_1.png" alt="创建&quot;或&quot;过渡"></p><h2 id="​-配置过渡" tabindex="-1"><a href="#configuring-a-transition">​</a> 配置过渡 <a class="header-anchor" href="#​-配置过渡" aria-label="Permalink to &quot;[​](#configuring-a-transition) 配置过渡&quot;">​</a></h2><p>选中过渡的方向指示器后，可以配置三个部分：过渡属性、条件和插值。</p><h3 id="​-过渡属性" tabindex="-1"><a href="#transition-properties">​</a> 过渡属性 <a class="header-anchor" href="#​-过渡属性" aria-label="Permalink to &quot;[​](#transition-properties) 过渡属性&quot;">​</a></h3><p><img src="https://help.rive.app/images/9b35e6bf-8e06-4df9-b211-10d3e1150435.webp" alt="过渡属性面板"></p><h3 id="​-持续时间-duration" tabindex="-1"><a href="#duration">​</a> 持续时间 (Duration) <a class="header-anchor" href="#​-持续时间-duration" aria-label="Permalink to &quot;[​](#duration) 持续时间 (Duration)&quot;">​</a></h3><p>描述过渡完成所需的时间。默认为 0（立即切换），增加该值会让过渡更平滑。 <img src="https://help.rive.app/images/image_3.png" alt="持续时间效果对比"> 过渡本质上是一种动画：起始属性来自离开的状态，结束属性来自进入的状态，Duration 就是两者之间的插值时间。</p><h3 id="​-退出时间-exit-time" tabindex="-1"><a href="#exit-time">​</a> 退出时间 (Exit Time) <a class="header-anchor" href="#​-退出时间-exit-time" aria-label="Permalink to &quot;[​](#exit-time) 退出时间 (Exit Time)&quot;">​</a></h3><p>指定在过渡之前，当前状态必须播放多长时间或多少百分比。 <img src="https://help.rive.app/images/image_6.png" alt="退出时间设置"> 例如：希望动画播放完整再过渡，可设置为 100%。</p><h3 id="​-退出时暂停-pause-when-exiting" tabindex="-1"><a href="#pause-when-exiting">​</a> 退出时暂停 (Pause when exiting) <a class="header-anchor" href="#​-退出时暂停-pause-when-exiting" aria-label="Permalink to &quot;[​](#pause-when-exiting) 退出时暂停 (Pause when exiting)&quot;">​</a></h3><p>过渡发生时，离开的状态是否暂停播放。 <img src="https://help.rive.app/images/image_7.png" alt="暂停效果"></p><h3 id="​-条件-conditions" tabindex="-1"><a href="#conditions">​</a> 条件 (Conditions) <a class="header-anchor" href="#​-条件-conditions" aria-label="Permalink to &quot;[​](#conditions) 条件 (Conditions)&quot;">​</a></h3><p>条件是触发过渡的规则。没有条件，过渡会持续触发导致混乱。条件需要定义输入 (Inputs)。 <img src="https://help.rive.app/images/a5336985-e1d4-4892-a04a-deee93e6a8b1.webp" alt="条件面板"></p><h4 id="添加条件" tabindex="-1">添加条件 <a class="header-anchor" href="#添加条件" aria-label="Permalink to &quot;添加条件&quot;">​</a></h4><p>点击 Conditions 旁的加号，选择输入类型（布尔值、数字或触发器）。</p><ul><li><strong>布尔值 (Boolean)</strong>：设置 true 或 false 时触发。</li><li><strong>数字 (Number)</strong>：等于、大于或小于某值时触发。</li><li><strong>触发器 (Trigger)</strong>：触发时执行过渡。</li></ul><p>多个条件构成&quot;与 (AND)&quot;逻辑。</p><h3 id="​-插值-interpolation" tabindex="-1"><a href="#interpolation">​</a> 插值 (Interpolation) <a class="header-anchor" href="#​-插值-interpolation" aria-label="Permalink to &quot;[​](#interpolation) 插值 (Interpolation)&quot;">​</a></h3><p>可在过渡面板底部设置插值曲线（线性、三次方或定格）。持续时间越长，插值效果越明显。 了解更多：<a href="https://help.rive.app/editor/animate-mode/interpolation-easing" target="_blank" rel="noreferrer">插值与缓动</a>。</p><p><a href="/docs/editor/state-machine/inputs">输入 (Inputs)</a><a href="/docs/editor/state-machine/listeners">监听器 (Listeners)</a></p>',24)])])}const u=e(r,[["render",o]]);export{m as __pageData,u as default};
